"""`cdk sync`: every generated file in the repo, rendered from platform.yaml + every deployment.yml.

Generated files are committed (so Atlantis, GitHub and editors see them) and
CI runs `cdk sync --check` so they can't drift.
"""

from __future__ import annotations

import json
import os
from pathlib import Path

from cdk.compile import compile_product
from cdk.model import Product, Repo
from cdk.schema import all_schemas

GENERATED = "GENERATED by `cdk sync`. Do not edit."


MOCK_PROVIDER = """mock_provider "google" {
  mock_data "google_project" {
    defaults = { number = "123456789" }
  }
  mock_resource "google_service_account" {
    defaults = { name = "projects/p/serviceAccounts/mock@p.iam.gserviceaccount.com" }
  }
  mock_resource "google_cloud_run_v2_job" {
    defaults = { id = "projects/p/locations/r/jobs/mock" }
  }
}
"""


def _deploy_files(repo: Repo, prod: Product) -> dict[Path, str]:
    deploy = prod.path / "deploy"
    rel_root = os.path.relpath(repo.root, deploy)
    rel_module = os.path.relpath(repo.modules_dir / "product", deploy)
    files = {
        deploy / "main.tf": f"""# {GENERATED}
# Inputs: <env>.tfvars.json, compiled from {rel_root}/platform.yaml and
# ../<section>/<name>/deployment.yml. Atlantis runs: plan -var-file=<env>.tfvars.json

terraform {{
  required_version = ">= 1.7"
  required_providers {{
    google = {{ source = "hashicorp/google", version = "~> 8.11" }}
  }}
  # bucket + prefix come from backend.<env>.hcl (Atlantis passes it at init)
  backend "gcs" {{}}
}}

provider "google" {{}}

variable "config" {{
  description = "The product for one env, as compiled by `cdk sync`"
  type        = any
}}

module "product" {{
  source = "{rel_module}"

  product             = var.config.product
  team                = var.config.team
  env                 = var.config.env
  project_id          = var.config.project_id
  region              = var.config.region
  labels              = var.config.labels
  vpc                 = var.config.vpc
  deployers           = var.config.deployers
  deletion_protection = var.config.deletion_protection

  services     = var.config.services
  jobs         = var.config.jobs
  worker_pools = var.config.worker_pools
  functions    = var.config.functions
}}

output "workloads" {{
  value = module.product.workloads
}}
""",
    }
    runs = []
    for env in prod.envs:
        bucket = repo.platform["envs"][env]["state_bucket"]
        files[deploy / f"backend.{env}.hcl"] = f'# {GENERATED}\nbucket = "{bucket}"\nprefix = "products/{prod.name}"\n'
        files[deploy / f"{env}.tfvars.json"] = json.dumps(compile_product(prod, env), indent=2, sort_keys=True) + "\n"
        runs.append(
            f'run "plan_{env}" {{\n'
            "  command = plan\n"
            f'  variables {{\n    config = jsondecode(file("{env}.tfvars.json")).config\n  }}\n'
            "  assert {\n"
            f"    condition     = length(output.workloads) == {len(prod.components)}\n"
            f'    error_message = "{env}: expected {len(prod.components)} workloads"\n'
            "  }\n}\n"
        )
    files[deploy / "tests" / "plan.tftest.hcl"] = (
        f"# {GENERATED}\n"
        "# Plans every env against a mocked provider: no GCP access needed, run in CI.\n"
        "#   terraform init -backend=false && terraform test\n\n" + MOCK_PROVIDER + "\n" + "\n".join(runs)
    )
    return files


def _atlantis(repo: Repo) -> str:
    lines = [f"# {GENERATED}", "version: 3", "automerge: false", "parallel_plan: true", "parallel_apply: false"]
    lines.append("projects:" if repo.products else "projects: []")
    for prod in repo.products.values():
        deploy = prod.path / "deploy"
        rel_modules = os.path.relpath(repo.modules_dir, deploy)
        for env in prod.envs:
            lines += [
                f"  - name: {prod.name}-{env}",
                f"    dir: {repo.rel(deploy)}",
                f"    workspace: {env}",
                "    workflow: cdk",
                "    autoplan:",
                "      enabled: true",
                f'      when_modified: ["*.tf", "backend.{env}.hcl", "{env}.tfvars.json", "{rel_modules}/**/*.tf"]',
            ]
    return "\n".join(lines) + "\n"


def _codeowners(repo: Repo) -> str:
    p = repo.platform
    owner = f"@{p['github_org']}/{p['team']}"
    return f"# {GENERATED}\n# One team owns this repo (platform.yaml: github_org, team).\n\n* {owner}\n"


PYTHON = "python3.13"  # matches the templates' base image and requires-python


def _pyright(repo: Repo) -> str:
    """basedpyright/pylance config: each Python component resolves imports from its own .venv."""
    comps = [repo.rel(c.path) for c in repo.components() if c.language == "python"]
    cfg = {
        "include": ["tools/cdk/src", "tools/cdk/tests"],
        "exclude": ["**/.venv", "**/node_modules", "**/__pycache__"],
        "pythonVersion": PYTHON.removeprefix("python"),
        "typeCheckingMode": "standard",
        "venvPath": ".",
        "venv": ".venv",
        "executionEnvironments": [
            *({"root": d, "extraPaths": [f"{d}/.venv/lib/{PYTHON}/site-packages"]} for d in comps),
            {"root": "tools/cdk", "extraPaths": ["tools/cdk/tests"]},
        ],
    }
    return f"// {GENERATED}\n" + json.dumps(cfg, indent=2) + "\n"


def render(repo: Repo) -> dict[Path, str]:
    files: dict[Path, str] = {}
    for prod in repo.products.values():
        files.update(_deploy_files(repo, prod))
    files[repo.root / "atlantis.yaml"] = _atlantis(repo)
    files[repo.root / "CODEOWNERS"] = _codeowners(repo)
    files[repo.root / "pyrightconfig.json"] = _pyright(repo)
    for name, schema in all_schemas(list(repo.platform["envs"])).items():
        files[repo.schema_dir / name] = json.dumps(schema, indent=2) + "\n"
    return files


def stale(repo: Repo, wanted: dict[Path, str]) -> list[Path]:
    """Generated files that should no longer exist (removed env, removed product)."""
    patterns = [
        "*/deploy/backend.*.hcl",
        "*/deploy/*.tfvars.json",
        "*/deploy/main.tf",
        "*/deploy/tests/plan.tftest.hcl",
    ]
    out = [p for pat in patterns for p in repo.products_dir.glob(pat) if p not in wanted]
    out += [p for p in repo.schema_dir.glob("*.schema.json") if p not in wanted]
    return out


def sync(repo: Repo, check: bool = False) -> list[str]:
    """Write (or with check=True, just list) generated files that differ. Returns their paths."""
    wanted = render(repo)
    changed = [p for p, content in wanted.items() if not p.exists() or p.read_text() != content]
    remove = stale(repo, wanted)
    if not check:
        for p in changed:
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(wanted[p])
        for p in remove:
            p.unlink()
    return [repo.rel(p) for p in changed] + [f"{repo.rel(p)} (delete)" for p in remove]
